// ============================================================
// 0. INISIALISASI STATE & ACCUMULATORS
// ============================================================
if (!flow.get("isRunning")) flow.set("isRunning", false);
if (!flow.get("isLapActive")) flow.set("isLapActive", false);

// Variabel Delta (Untuk menghindari error saat ESP32 restart)
if (!flow.get("prevRawEnergy")) flow.set("prevRawEnergy", 0);
if (!flow.get("prevRawDistance")) flow.set("prevRawDistance", 0);

// Variabel Akumulasi Sesi & Lap
if (!flow.get("sessionEnergy")) flow.set("sessionEnergy", 0);
if (!flow.get("sessionDistance")) flow.set("sessionDistance", 0);
if (!flow.get("lapEnergyAcc")) flow.set("lapEnergyAcc", 0);
if (!flow.get("lapDistanceAcc")) flow.set("lapDistanceAcc", 0);

if (!flow.get("lapStartTime")) flow.set("lapStartTime", Date.now());
if (!flow.get("lapCounter")) flow.set("lapCounter", 0);

// === TAMBAHAN UNTUK CARRY-OVER (STACKING) ===
if (!flow.get("carryOver")) flow.set("carryOver", 0);
if (!flow.get("targetTime")) flow.set("targetTime", 200); // detik, bisa disesuaikan

// ============================================================
// 1. TANGANI PERINTAH TOMBOL
// ============================================================
if (msg.payload === "START_SESSION") {
    flow.set("isRunning", true);
    flow.set("isLapActive", true);
    flow.set("lapStartTime", Date.now());

    // Reset Akumulator
    flow.set("sessionEnergy", 0);
    flow.set("sessionDistance", 0);
    flow.set("lapEnergyAcc", 0);
    flow.set("lapDistanceAcc", 0);
    flow.set("lapCounter", 1);

    // Reset UI Last Lap
    flow.set("lastLapTime", "--:--.---");
    flow.set("lastLapEnergy", "0.00");
    flow.set("lastLapKmPerKwh", "0.00");

    // Reset carry-over
    flow.set("carryOver", 0);

    return [null, null, null, null, { payload: { cmd: "START", timestamp: Date.now() } }, null];
}

if (msg.payload === "RECORD_LAP") {
    if (!flow.get("isRunning")) return [null, null, null, null, null, null];

    // 1. Ambil data akumulasi lap yang baru saja selesai
    let energyUsed = flow.get("lapEnergyAcc") || 0;
    let lapDistance = flow.get("lapDistanceAcc") || 0;

    // 2. Hitung Waktu Lap (durasi aktual)
    let startTime = flow.get("lapStartTime") || Date.now();
    let elapsed = (Date.now() - startTime) / 1000;
    let m = Math.floor(elapsed / 60);
    let s = Math.floor(elapsed % 60);
    let ms = Math.floor((elapsed % 1) * 1000);
    let lapStr = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;

    // 3. Hitung km/kWh untuk lap ini (dengan pengaman)
    let kmPerKwh = 0.00;
    if (lapDistance > 0.01 && energyUsed > 0.1) {
        kmPerKwh = lapDistance / (energyUsed / 1000);
        if (kmPerKwh > 100) kmPerKwh = 100;
    }

    // 4. Simpan hasil lap ke UI
    flow.set("lastLapTime", lapStr);
    flow.set("lastLapEnergy", energyUsed.toFixed(2));
    flow.set("lastLapKmPerKwh", kmPerKwh.toFixed(2));

    // 5. Akumulasi carry-over (stacking) dari sisa waktu lap ini
    let targetTime = flow.get("targetTime") || 200;
    let remaining = targetTime - elapsed;
    let carryOver = flow.get("carryOver") || 0;
    carryOver += remaining;
    // Batasi agar effective target tidak kurang dari 1 detik (seperti di HP)
    if (carryOver < 1 - targetTime) carryOver = 1 - targetTime;
    flow.set("carryOver", carryOver);

    // 6. Reset akumulator khusus Lap (Sesi utama tetap berlanjut)
    flow.set("lapEnergyAcc", 0);
    flow.set("lapDistanceAcc", 0);
    flow.set("lapStartTime", Date.now());
    flow.set("lapCounter", (flow.get("lapCounter") || 1) + 1);

    return [null, null, null, null, { payload: { cmd: "LAP", timestamp: Date.now() } }, null];
}

if (msg.payload === "RESET_ALL") {
    flow.set("isRunning", false);
    flow.set("isLapActive", false);
    flow.set("lapStartTime", Date.now());
    flow.set("sessionEnergy", 0);
    flow.set("sessionDistance", 0);
    flow.set("lapEnergyAcc", 0);
    flow.set("lapDistanceAcc", 0);
    flow.set("lapCounter", 0);

    flow.set("lastLapTime", "--:--.---");
    flow.set("lastLapEnergy", "0.00");
    flow.set("lastLapKmPerKwh", "0.00");

    flow.set("carryOver", 0);  // reset carry-over

    return [null, null, null, null, { payload: { cmd: "RESET", timestamp: Date.now() } }, null];
}

// ============================================================
// TANGANI LAP_RESULT DARI HP (diterima tapi diabaikan agar tidak mengganggu)
// ============================================================
if (msg.payload && msg.payload.type === "LAP_RESULT") {
    // Bisa digunakan untuk sinkronisasi, tetapi di sini kita abaikan
    // karena laptop sudah menghitung sendiri.
    return [null, null, null, null, null, null];
}

// ============================================================
// 2. PARSING DATA MQTT
// ============================================================
let str = msg.payload.toString().trim();
let parts = str.split(",");
if (parts.length < 11) return [null, null, null, null, null, null];

let lat = parseFloat(parts[0]) || 0;
let lng = parseFloat(parts[1]) || 0;
let speed = parseFloat(parts[2]) || 0;
let sat = parseInt(parts[3]) || 0;
let throttle = parseInt(parts[4]) || 0;
let current_mA = parseFloat(parts[5]) || 0;
let voltage = parseFloat(parts[6]) || 0;
let power = parseFloat(parts[7]) || 0;
let energyRaw = parseFloat(parts[8]) || 0;
let distanceRaw = parseFloat(parts[9]) || 0;
let millis = parseFloat(parts[10]) || 0;
let current_A = current_mA / 1000.0;

// ============================================================
// 3. LOGIKA AKUMULASI (KEBAL RESTART)
// ============================================================
let prevRawEnergy = flow.get("prevRawEnergy") || 0;
let prevRawDist = flow.get("prevRawDistance") || 0;

let deltaEnergy = energyRaw - prevRawEnergy;
let deltaDist = distanceRaw - prevRawDist;

if (deltaEnergy < 0) deltaEnergy = energyRaw;
if (deltaDist < 0) deltaDist = distanceRaw;

flow.set("prevRawEnergy", energyRaw);
flow.set("prevRawDistance", distanceRaw);

if (flow.get("isRunning")) {
    flow.set("sessionEnergy", (flow.get("sessionEnergy") || 0) + deltaEnergy);
    flow.set("sessionDistance", (flow.get("sessionDistance") || 0) + deltaDist);

    flow.set("lapEnergyAcc", (flow.get("lapEnergyAcc") || 0) + deltaEnergy);
    flow.set("lapDistanceAcc", (flow.get("lapDistanceAcc") || 0) + deltaDist);
}

let displayTotalEnergy = flow.get("isRunning") ? flow.get("sessionEnergy") : 0;
let displayTotalDistance = flow.get("isRunning") ? flow.get("sessionDistance") : 0;
let displayLapEnergy = flow.get("isRunning") ? flow.get("lapEnergyAcc") : 0;

let displayKmPerKwhTotal = 0.00;
if (flow.get("isRunning") && displayTotalDistance > 0.05 && displayTotalEnergy > 0.5) {
    displayKmPerKwhTotal = displayTotalDistance / (displayTotalEnergy / 1000);
    if (displayKmPerKwhTotal > 100) displayKmPerKwhTotal = 100;
}

// ============================================================
// 4. TIMER & REMAINING ENERGY (dengan CARRY-OVER)
// ============================================================
let targetEnergy = 7.0;
let remainingEnergy = Math.max(0, targetEnergy - displayLapEnergy);

let targetTime = flow.get("targetTime") || 200;
let carryOver = flow.get("carryOver") || 0;
let effectiveTarget = Math.max(1, targetTime + carryOver);  // pastikan minimal 1 detik

let startTime = flow.get("lapStartTime") || Date.now();
let elapsedSec = (Date.now() - startTime) / 1000;
let remainingSec = effectiveTarget - elapsedSec;

let currentLap, countdown, countdownColor;
if (!flow.get("isRunning")) {
    currentLap = "--:--.---";
    countdown = "--:--.---";
    countdownColor = "#666";
} else {
    function fmtTime(sec) {
        let m = Math.floor(Math.abs(sec) / 60);
        let s = Math.floor(Math.abs(sec) % 60);
        let ms = Math.floor((Math.abs(sec) % 1) * 1000);
        let sign = sec < 0 ? '-' : '';
        return `${sign}${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;
    }
    currentLap = fmtTime(elapsedSec);
    countdown = fmtTime(remainingSec);
    countdownColor = remainingSec <= 0 ? "#ff0044" : (remainingSec <= 60 ? "#ffff00" : "#00ff00");
}

// ============================================================
// 5. PENYUSUNAN OUTPUT
// ============================================================
let msgTemplate = {
    payload: {
        speed: speed.toFixed(0),
        speedPct: Math.min((speed / 50) * 100, 100).toFixed(1),
        current: current_A.toFixed(2),
        voltage: voltage.toFixed(1),
        power: power.toFixed(0),
        energy: displayLapEnergy.toFixed(2),
        remEnergy: remainingEnergy.toFixed(2),
        throttle: throttle,
        sat: sat,
        currentLap: currentLap,
        countdown: countdown,
        countdownColor: countdownColor,
        lastLapTime: flow.get("lastLapTime") || "--:--.---",
        lastLapEnergy: flow.get("lastLapEnergy") || "0.00",
        lastLapKmPerKwh: flow.get("lastLapKmPerKwh") || "0.00",
        distance: displayTotalDistance.toFixed(2),
        kmPerKwh: displayKmPerKwhTotal.toFixed(2)
    }
};

let msgMap = {
    payload: { name: "RAKATA_EV", lat, lon: lng, heading: 0, icon: "fa-location-arrow", iconColor: "red", track: true, ttl: 180 }
};

let telemetryMsg = null;
if (flow.get("isRunning")) {
    let now = new Date().toISOString();
    let telemetryLine = `${now},${lat.toFixed(6)},${lng.toFixed(6)},${speed.toFixed(2)},${sat},${throttle},${current_mA.toFixed(3)},${voltage.toFixed(2)},${power.toFixed(2)},${energyRaw.toFixed(4)},${displayTotalDistance.toFixed(3)},${millis}`;
    telemetryMsg = { payload: telemetryLine };
}

// Output urutan: [ui_template, ui_worldmap, null, file, mqtt out, null]
return [msgTemplate, msgMap, null, telemetryMsg, null, null];

// Independent elevation branch. No writes to original telemetry state.
let st=flow.get('elev_v1')||{epoch:0,points:[],cache:{},s:0,segment:0,seq:0};
const now=Date.now(),p=msg.payload||{};
if(p.cmd==='START'||p.cmd==='RESET'){
 st.epoch++;st.points=[];st.s=0;st.prev=null;st.pending=null;st.segment++;st.lastSample=null;
 flow.set('elev_v1',st);return [null,{_elevReset:true,payload:{}}];
}
if(p.cmd||!flow.get('isRunning'))return null;
const lat=Number(p.lat),lon=Number(p.lon);
if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||(lat===0&&lon===0))return null;
const rad=Math.PI/180;
function metres(a,b){let q=Math.sin((b.lat-a.lat)*rad/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin((b.lon-a.lon)*rad/2)**2;return 12742000*Math.asin(Math.sqrt(Math.min(1,q)));}
const cur={lat,lon,t:now};
if(st.prev){
 const dt=(now-st.prev.t)/1000,ds=metres(st.prev,cur);
 if(dt>5||ds>Math.max(10,dt*60/3.6)){st.segment++;st.lastSample=null;}
 else if(ds>=1)st.s+=ds;
}
st.prev=cur;
if(st.pending&&now-st.pending.t<15000){flow.set('elev_v1',st);return null;}
if(st.lastSample&&st.s-st.lastSample.s<20&&st.segment===st.lastSample.segment){flow.set('elev_v1',st);return null;}
if(now-(st.lastTry||0)<10000){flow.set('elev_v1',st);return null;}
const key=lat.toFixed(4)+','+lon.toFixed(4);
const meta={epoch:st.epoch,id:++st.seq,s:st.s,t:now,segment:st.segment,key};
st.lastTry=now;st.lastSample=meta;
if(st.cache[key]!==undefined){flow.set('elev_v1',st);return [null,{_elev:meta,payload:{status:'OK',results:[{elevation:st.cache[key]}]}}];}
const day=new Date(now).toISOString().slice(0,10);if(st.day!==day){st.day=day;st.calls=0;}
if(st.calls>=950){flow.set('elev_v1',st);return [null,{_elev:meta,payload:{status:'LIMIT'}}];}
st.calls++;st.pending=meta;flow.set('elev_v1',st);
return [{_elev:meta,method:'GET',url:'https://api.opentopodata.org/v1/srtm30m?locations='+encodeURIComponent(key)+'&interpolation=bilinear',payload:''},null];

let st=flow.get('elev_v1');if(!st)return null;
if(msg._elevReset)return {payload:{points:[],status:'Menunggu GPS',last:'—',elevation:null,grade:null}};
const m=msg._elev;if(!m||m.epoch!==st.epoch)return null;
if(st.pending&&st.pending.id===m.id)st.pending=null;
if(st.lastAccepted&&m.id<=st.lastAccepted&&st.acceptedEpoch===m.epoch)return null;
let body=msg.payload;if(typeof body==='string'){try{body=JSON.parse(body);}catch(e){body={};}}
const value=body&&body.status==='OK'&&body.results&&body.results[0]?body.results[0].elevation:null;
let status='API gagal · data terakhir';
if(body&&body.status==='LIMIT')status='Batas API · data terakhir';
if(typeof value==='number'&&Number.isFinite(value)&&!msg.error&&(!msg.statusCode||msg.statusCode===200)){
 st.lastAccepted=m.id;st.acceptedEpoch=m.epoch;
 st.cache[m.key]=value;const keys=Object.keys(st.cache);if(keys.length>600)delete st.cache[keys[0]];
 let grade=null;
 // Backward mean slope over >=50 m in one uninterrupted trace, not instant tilt.
 for(let i=st.points.length-1;i>=0;i--){const a=st.points[i];if(a.segment!==m.segment)break;if(m.s-a.s>=50){if(m.s-a.s<=150)grade=100*(value-a.h)/(m.s-a.s);break;}}
 st.points.push({s:m.s,h:value,g:grade,t:m.t,segment:m.segment});st.points=st.points.slice(-300);
 status='SRTM 30 m · estimasi';
}else{st.lastSample=null;st.segment++;}
flow.set('elev_v1',st);
const last=st.points[st.points.length-1];
return {payload:{points:st.points,status,last:last?new Date(last.t).toLocaleTimeString():'—',elevation:last?last.h:null,grade:last?last.g:null}};
